package dev.thefoolish.generated.anishelf;
import android.app.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.os.*;import android.view.*;import android.widget.*;
public abstract class AppScreen extends Activity{protected LinearLayout body;protected LocalStore store;private TextView topTitle;private LinearLayout bottomNav;protected final int BG=Color.rgb(15,17,22),SURFACE=Color.rgb(27,30,38),SURFACE2=Color.rgb(36,40,50),TEXT=Color.rgb(238,240,246),MUTED=Color.rgb(164,171,187),ACCENT=Color.rgb(111,125,255);@Override public void onCreate(Bundle state){super.onCreate(state);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);store=new LocalStore(this);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(BG);LinearLayout appBar=new LinearLayout(this);appBar.setOrientation(LinearLayout.VERTICAL);appBar.setBackgroundColor(BG);appBar.setPadding(dp(20),dp(12),dp(20),dp(10));TextView brand=text("AniShelf",12,false);brand.setTextColor(MUTED);brand.setPadding(0,0,0,dp(2));appBar.addView(brand);topTitle=text("Browse",24,true);appBar.addView(topTitle);root.addView(appBar,new LinearLayout.LayoutParams(-1,-2));ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(16),dp(8),dp(16),dp(24));scroll.addView(body,new ScrollView.LayoutParams(-1,-2));root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));bottomNav=new LinearLayout(this);bottomNav.setOrientation(LinearLayout.HORIZONTAL);bottomNav.setBackgroundColor(SURFACE);bottomNav.setPadding(dp(6),dp(6),dp(6),dp(6));root.addView(bottomNav,new LinearLayout.LayoutParams(-1,-2));buildBottomNav();setContentView(root);if(Build.VERSION.SDK_INT>=21){root.setOnApplyWindowInsetsListener((v,insets)->{int top=insets.getSystemWindowInsetTop();int bottom=insets.getSystemWindowInsetBottom();appBar.setPadding(dp(20),top+dp(10),dp(20),dp(10));bottomNav.setPadding(dp(6),dp(6),dp(6),bottom+dp(6));return insets;});root.requestApplyInsets();}render();}protected abstract void render();protected void title(String s){topTitle.setText(s==null?"":s);}protected void subtitle(String s){TextView t=text(s,14,false);t.setTextColor(MUTED);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,0,0,dp(12));body.addView(t,p);}protected void section(String s){TextView t=text(s,18,true);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(10),0,dp(8));body.addView(t,p);}protected TextView text(String value,int size,boolean bold){TextView t=new TextView(this);t.setText(value);t.setTextColor(TEXT);t.setTextSize(size);t.setTypeface(android.graphics.Typeface.create("sans-serif",bold?1:0));t.setGravity(Gravity.CENTER_VERTICAL);return t;}protected Button button(String label){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setTextSize(14);b.setTextColor(TEXT);b.setMinHeight(dp(48));b.setContentDescription(label);b.setBackground(round(SURFACE2,14));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(50));p.setMargins(0,dp(6),0,dp(6));b.setLayoutParams(p);return b;}protected LinearLayout card(String heading,String supporting){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(16),dp(14),dp(16),dp(14));c.setBackground(round(SURFACE,16));TextView h=text(heading,16,true);c.addView(h);if(supporting!=null&&supporting.length()>0){TextView s=text(supporting,13,false);s.setTextColor(MUTED);s.setPadding(0,dp(4),0,0);c.addView(s);}LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,0,0,dp(10));c.setLayoutParams(p);return c;}protected GradientDrawable round(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}protected void nav(){}private void buildBottomNav(){String[] names={"Library","Updates","History","Browse","More"};Class[] screens={LibraryActivity.class,UpdatesActivity.class,HistoryActivity.class,MainActivity.class,MoreActivity.class};for(int i=0;i<names.length;i++){final Class target=screens[i];TextView item=text(names[i],11,false);item.setGravity(Gravity.CENTER);item.setMinHeight(dp(52));item.setPadding(dp(4),0,dp(4),0);item.setContentDescription("Open "+names[i]);item.setOnClickListener(v->AppNavigator.open(this,target));bottomNav.addView(item,new LinearLayout.LayoutParams(0,dp(52),1));}}protected int dp(int v){return (int)(v*getResources().getDisplayMetrics().density+.5f);}}
